* { box-sizing: border-box; }
:root { color-scheme: dark; --ink: #19252b; --panel: #24343b; --panel-light: #2d4149; --cream: #f5efdc; --muted: #b5c5bb; --mint: #a8d5a2; --orange: #f0a36b; --line: #43565c; }
body { margin: 0; min-height: 100vh; padding: 32px 16px; display: grid; place-items: start center; background-color: var(--ink); background-image: radial-gradient(#35464b 1px, transparent 1px); background-size: 18px 18px; color: var(--cream); font: 16px/1.5 system-ui, sans-serif; }
.board { width: min(100%, 560px); padding: 28px; background: var(--panel); border: 2px solid #52665e; border-radius: 8px; box-shadow: 8px 8px 0 #10191d; }
.header { display: flex; gap: 16px; align-items: center; margin-bottom: 26px; }
.pixel-mark { width: 54px; height: 54px; display: grid; place-items: center; flex: 0 0 auto; color: var(--ink); background: var(--mint); border: 3px solid var(--cream); box-shadow: 4px 4px 0 var(--orange); font-size: 30px; font-weight: 900; }
.eyebrow { margin: 0; color: var(--mint); font-size: 13px; font-weight: 800; letter-spacing: .16em; }
h1 { margin: 0; font-size: clamp(23px, 6vw, 31px); line-height: 1.18; }
.subtitle { margin: 4px 0 0; color: var(--muted); }
h2 { margin: 0; font-size: 19px; }
.entry, .items-section, .tip-section { padding: 18px 0; border-top: 1px solid var(--line); }
.entry h2 { margin-bottom: 14px; }
.form-row { display: flex; gap: 12px; }
.field { display: grid; gap: 7px; color: var(--muted); font-size: 14px; font-weight: 700; }
.item-field { flex: 1; min-width: 0; }
.price-field { width: 128px; flex: 0 0 auto; }
input[type="text"], input[type="number"] { width: 100%; min-height: 46px; padding: 10px 12px; border: 2px solid var(--line); border-radius: 4px; outline: none; background: var(--ink); color: var(--cream); font: inherit; }
input::placeholder { color: #84978f; }
input:focus-visible, button:focus-visible, .person-option:focus-within { outline: 3px solid var(--orange); outline-offset: 3px; }
.people-picker { min-width: 0; margin: 17px 0 14px; padding: 0; border: 0; }
.people-picker legend { margin-bottom: 9px; color: var(--muted); font-size: 14px; font-weight: 700; }
.check-row { display: flex; gap: 10px; flex-wrap: wrap; }
.person-option { display: inline-flex; align-items: center; gap: 8px; min-height: 44px; padding: 7px 12px; border: 1px solid var(--line); border-radius: 4px; cursor: pointer; }
.person-option:hover { background: var(--panel-light); }
.person-option input { position: absolute; width: 1px; height: 1px; opacity: 0; }
.check-box { width: 18px; height: 18px; display: grid; place-items: center; border: 2px solid var(--muted); border-radius: 3px; }
.person-option input:checked + .check-box { background: var(--mint); border-color: var(--mint); }
.person-option input:checked + .check-box::after { content: "✓"; color: var(--ink); font-size: 14px; font-weight: 900; line-height: 1; }
.button { min-height: 46px; padding: 9px 16px; border: 2px solid var(--mint); border-radius: 4px; background: var(--mint); color: var(--ink); font: inherit; font-weight: 800; cursor: pointer; transition: transform .08s, background .12s; }
.button:hover { background: #bee5b7; }
.button:active { transform: translate(2px, 2px); }
.add-button span { font-size: 21px; vertical-align: -1px; }
.error { margin: 10px 0 0; color: #ffb28d; font-size: 14px; }
[hidden] { display: none !important; }
.section-heading { display: flex; justify-content: space-between; align-items: center; gap: 12px; }
.count-badge { padding: 3px 9px; border: 1px solid var(--line); border-radius: 99px; color: var(--muted); font-size: 13px; }
.item-list { list-style: none; padding: 0; margin: 12px 0 0; }
.item-row { display: flex; align-items: center; gap: 10px; padding: 10px 0; border-bottom: 1px dashed var(--line); }
.item-info { min-width: 0; flex: 1; }
.item-name { display: block; overflow-wrap: anywhere; font-weight: 700; }
.item-people { display: block; color: var(--muted); font-size: 13px; }
.item-price { font-variant-numeric: tabular-nums; font-weight: 700; }
.remove-button { width: 38px; height: 38px; border: 1px solid var(--line); border-radius: 4px; background: transparent; color: var(--muted); font: inherit; font-size: 20px; cursor: pointer; }
.remove-button:hover { border-color: var(--orange); color: var(--orange); background: #3b3c38; }
.remove-button:active { transform: scale(.94); }
.empty-state { margin: 14px 0 0; color: var(--muted); }
.tip-section { display: grid; grid-template-columns: auto auto 1fr; align-items: center; gap: 10px; }
.tip-section > label { font-weight: 800; }
.tip-control { display: flex; align-items: center; gap: 6px; }
.tip-control input { width: 80px; min-height: 42px; padding: 6px 8px; }
.tip-section p { margin: 0; color: var(--muted); font-size: 13px; }
.totals { padding: 18px; border: 1px solid #52665e; border-radius: 5px; background: var(--ink); }
.pixel-spark { color: var(--orange); font-size: 23px; }
.total-list { margin-top: 10px; }
.total-row { display: flex; justify-content: space-between; gap: 12px; padding: 9px 0; border-bottom: 1px solid #33434a; }
.total-person { font-weight: 700; }
.total-detail { display: block; color: var(--muted); font-size: 13px; font-weight: 400; }
.total-amount { color: var(--mint); font-size: 19px; font-weight: 800; font-variant-numeric: tabular-nums; }
.grand-total { display: flex; justify-content: space-between; gap: 12px; padding-top: 14px; color: var(--muted); }
.grand-total strong { color: var(--cream); font-size: 20px; font-variant-numeric: tabular-nums; }
footer { margin-top: 18px; color: var(--muted); text-align: center; font-size: 13px; }
@media (max-width: 420px) { body { padding: 16px 10px; } .board { padding: 20px 16px; } .form-row { gap: 8px; } .price-field { width: 110px; } .tip-section { grid-template-columns: auto auto; } .tip-section p { grid-column: 1 / -1; } }
@media (prefers-reduced-motion: reduce) { *, *::before, *::after { scroll-behavior: auto !important; transition-duration: .01ms !important; } }

(() => {
  const people = ['Alex', 'Blair', 'Casey'];
  const form = document.querySelector('#item-form');
  const nameInput = document.querySelector('#item-name');
  const priceInput = document.querySelector('#item-price');
  const tipInput = document.querySelector('#tip-percent');
  const list = document.querySelector('#item-list');
  const error = document.querySelector('#form-error');
  const items = [];
  const cents = value => Math.round(value * 100);
  const money = value => `$${(value / 100).toFixed(2)}`;

  function render() {
    list.replaceChildren();
    document.querySelector('#empty-state').hidden = items.length > 0;
    document.querySelector('#item-count').textContent = `${items.length} ${items.length === 1 ? 'item' : 'items'}`;

    items.forEach((item, index) => {
      const row = document.createElement('li');
      row.className = 'item-row';
      const info = document.createElement('div');
      info.className = 'item-info';
      const name = document.createElement('span');
      name.className = 'item-name';
      name.textContent = item.name;
      const shared = document.createElement('span');
      shared.className = 'item-people';
      shared.textContent = `Shared by ${item.people.map(i => people[i]).join(', ')}`;
      info.append(name, shared);
      const price = document.createElement('span');
      price.className = 'item-price';
      price.textContent = money(item.price);
      const remove = document.createElement('button');
      remove.className = 'remove-button';
      remove.type = 'button';
      remove.setAttribute('aria-label', `Remove ${item.name}`);
      remove.textContent = '×';
      remove.addEventListener('click', () => { items.splice(index, 1); render(); });
      row.append(info, price, remove);
      list.append(row);
    });

    const shares = [0, 0, 0];
    for (const item of items) {
      const base = Math.floor(item.price / item.people.length);
      let remainder = item.price - base * item.people.length;
      item.people.forEach(person => { shares[person] += base + (remainder-- > 0 ? 1 : 0); });
    }
    const tipPercent = Number(tipInput.value) || 0;
    const subtotal = shares.reduce((sum, amount) => sum + amount, 0);
    const tipTotal = Math.round(subtotal * tipPercent / 100);
    const tips = [0, 0, 0];
    if (subtotal > 0) {
      let remainingTip = tipTotal;
      shares.forEach((share, index) => {
        tips[index] = Math.floor(tipTotal * share / subtotal);
        remainingTip -= tips[index];
      });
      for (let i = 0; remainingTip > 0; i = (i + 1) % 3) {
        if (shares[i] > 0) { tips[i]++; remainingTip--; }
      }
    }
    const totalList = document.querySelector('#total-list');
    totalList.replaceChildren();
    people.forEach((person, index) => {
      const row = document.createElement('div');
      row.className = 'total-row';
      const label = document.createElement('span');
      label.className = 'total-person';
      label.append(document.createTextNode(person));
      const detail = document.createElement('span');
      detail.className = 'total-detail';
      detail.textContent = `Share ${money(shares[index])} + tip ${money(tips[index])}`;
      label.append(detail);
      const amount = document.createElement('span');
      amount.className = 'total-amount';
      amount.textContent = money(shares[index] + tips[index]);
      row.append(label, amount);
      totalList.append(row);
    });
    document.querySelector('#grand-total').textContent = money(subtotal + tipTotal);
  }

  form.addEventListener('submit', event => {
    event.preventDefault();
    error.hidden = true;
    const selected = [...form.querySelectorAll('input[name="person"]:checked')].map(input => Number(input.value));
    const price = Number(priceInput.value);
    if (!selected.length) {
      error.textContent = 'Choose at least one person to share this item.';
      error.hidden = false;
      form.querySelector('input[name="person"]').focus();
      return;
    }
    if (!Number.isFinite(price) || price <= 0 || price > 999999) {
      error.textContent = 'Enter a price greater than $0.00.';
      error.hidden = false;
      priceInput.focus();
      return;
    }
    items.push({ name: nameInput.value.trim(), price: cents(price), people: selected });
    form.reset();
    render();
    nameInput.focus();
  });
  tipInput.addEventListener('input', () => {
    const value = Number(tipInput.value);
    if (tipInput.value === '' || !Number.isFinite(value) || value < 0 || value > 100) return;
    render();
  });
  render();
})();
